import { describe, expect, it } from 'vitest';
import { parseLaunchOptions } from '../dev/LaunchOptions';
import {
  COURSES,
  COURSE_REGISTRY,
  COURSE_SUMMARIES,
  DEFAULT_COURSE_ID,
  LocalCourseRepository,
  RANDOM_COURSE_ID,
  getCourse,
  requireCourse,
  resolveCourseSelection,
} from './index';

describe('course registry', () => {
  it('registers all ten courses under their own id', () => {
    expect(COURSES).toHaveLength(10);
    expect(COURSE_REGISTRY.size).toBe(10);
    for (const course of COURSES) expect(COURSE_REGISTRY.get(course.id)).toBe(course);
    expect(COURSES.reduce((sum, course) => sum + course.holes.length, 0)).toBe(90);
  });

  it('exposes menu summaries aligned with the registry', () => {
    expect(COURSE_SUMMARIES.map(summary => summary.id)).toEqual(COURSES.map(course => course.id));
    for (const summary of COURSE_SUMMARIES) {
      const course = requireCourse(summary.id);
      expect(summary.name).toBe(course.name);
      expect(summary.holeCount).toBe(course.holes.length);
      expect(summary.totalPar).toBe(course.holes.reduce((sum, hole) => sum + hole.par, 0));
    }
  });

  it('resolves known ids and reports unknown ones', () => {
    expect(getCourse('volcano')?.id).toBe('volcano');
    expect(getCourse('starter-tour')).toBeUndefined();
    expect(getCourse(undefined)).toBeUndefined();
    expect(() => requireCourse('starter-tour')).toThrow(/Unknown course/);
    expect(requireCourse(DEFAULT_COURSE_ID).id).toBe(DEFAULT_COURSE_ID);
  });
});

describe('course selection', () => {
  it('starts the requested hole of ?course=volcano&hole=4', () => {
    const selection = resolveCourseSelection(parseLaunchOptions('?course=volcano&hole=4'));
    expect(selection.course.id).toBe('volcano');
    expect(selection.holeIndex).toBe(3);
    expect(selection.holeNumber).toBe(4);
    expect(selection.hole).toBe(selection.course.holes[3]);
    expect(selection.matchedCourse).toBe(true);
    expect(selection.matchedHole).toBe(true);
  });

  it('falls back to the default course and first hole', () => {
    const unknown = resolveCourseSelection({ courseId: 'starter-tour', hole: 2 });
    expect(unknown.course.id).toBe(DEFAULT_COURSE_ID);
    expect(unknown.matchedCourse).toBe(false);
    expect(unknown.holeNumber).toBe(2);

    const empty = resolveCourseSelection();
    expect(empty.course.id).toBe(DEFAULT_COURSE_ID);
    expect(empty.holeIndex).toBe(0);
    expect(empty.matchedHole).toBe(false);
  });

  it('clamps out-of-range holes back to the first hole', () => {
    const selection = resolveCourseSelection({ courseId: 'neon-city', hole: 42 });
    expect(selection.course.id).toBe('neon-city');
    expect(selection.holeIndex).toBe(0);
    expect(selection.matchedHole).toBe(false);
  });

  it('rolls a registered course for the random pseudo id', () => {
    const first = resolveCourseSelection({ courseId: RANDOM_COURSE_ID }, () => 0);
    const last = resolveCourseSelection({ courseId: RANDOM_COURSE_ID }, () => 0.999999);
    expect(first.course).toBe(COURSES[0]);
    expect(last.course).toBe(COURSES[COURSES.length - 1]);
    expect(first.matchedCourse).toBe(true);
  });
});

describe('LocalCourseRepository', () => {
  it('serves bundled courses through the repository contract', async () => {
    const repository = new LocalCourseRepository();
    await expect(repository.listCourses()).resolves.toHaveLength(10);
    await expect(repository.getCourse('pirate-bay')).resolves.toBe(requireCourse('pirate-bay'));
    await expect(repository.getCourse('starter-tour')).rejects.toThrow(/Unknown course/);
  });
});
